#include <bits/stdc++.h>
using namespace std;

int main() {
    int T;
    cin>>T;
    while(T--){
        int n;
        cin>>n;
        vector<long long>a(3*n);
        for(int i=0; i<3*n; i++)
           cin>>a[i];
        sort(a.rbegin(),a.rend());
        vector<long long>pref(3*n+1, 0);
        for(int i=0; i<3*n; i++)
            pref[i+1] = pref[i]+a[i];
        long long ans = 0;
        for(int A = 0; A<=n; A++){
            int low = 0;
            int high = n-A;
            while(low<=high){
                int B = (low+high)/2;
                int x = A+2*B;
                int y = 3*n-2*A-B;
                if(B<n-A){
                    long long change = a[x]+a[x+1]-3*a[y-1];
                    if(change >= 0)
                      low = B+1;
                    else
                      high = B-1;
                }
                else{
                    break;
                }
            }
            for(int B=max(0,high-1); B<=min(n-A,high+1); B++){
                int x = A+2*B;
                int y = 3*n-2*A-B;
                long long cur = 2*pref[A]+pref[x]+3*pref[y];
                ans = max(ans,cur);
            }
        }
        cout<<ans<<endl;
             
    }
    return 0;
}
